CREATE TABLE public.magic_ticket_test_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,ticket_codes text[] NOT NULL,asset_ids uuid[] NOT NULL,status text NOT NULL DEFAULT 'open',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,rolled_back_at timestamptz,rolled_back_by uuid,CONSTRAINT mt_session_status CHECK(status IN ('open','ended','rolling_back','rolled_back')));
GRANT SELECT ON public.magic_ticket_test_sessions TO authenticated; GRANT ALL ON public.magic_ticket_test_sessions TO service_role;
ALTER TABLE public.magic_ticket_test_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY mt_sessions_super_admin ON public.magic_ticket_test_sessions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.magic_ticket_test_documents(pending_id uuid PRIMARY KEY REFERENCES public.goods_issue_pending(id),session_id uuid NOT NULL REFERENCES public.magic_ticket_test_sessions(id),ticket_code text NOT NULL,captured_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.magic_ticket_test_documents TO authenticated; GRANT ALL ON public.magic_ticket_test_documents TO service_role;
ALTER TABLE public.magic_ticket_test_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY mt_test_docs_super_admin ON public.magic_ticket_test_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.magic_ticket_test_journal(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,session_id uuid NOT NULL REFERENCES public.magic_ticket_test_sessions(id),table_name text NOT NULL,row_id uuid NOT NULL,before_row jsonb,after_row jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.magic_ticket_test_journal TO authenticated; GRANT ALL ON public.magic_ticket_test_journal TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.magic_ticket_test_journal_id_seq TO service_role;
ALTER TABLE public.magic_ticket_test_journal ENABLE ROW LEVEL SECURITY;
CREATE POLICY mt_journal_super_admin ON public.magic_ticket_test_journal FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.mt_test_create(p_name text,p_start timestamptz,p_end timestamptz,p_tickets text[],p_assets uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN
IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'เฉพาะ Super Admin'; END IF;
PERFORM pg_advisory_xact_lock(hashtext('mt_test_sessions'));
IF length(trim(p_name)) NOT BETWEEN 1 AND 120 OR p_start IS NULL OR p_end IS NULL OR p_end<=p_start OR p_end<=now() OR p_start<now()-interval '5 minutes' OR coalesce(cardinality(p_tickets),0)=0 OR coalesce(cardinality(p_assets),0)=0 THEN RAISE EXCEPTION 'ระบุชื่อ ช่วงเวลาในอนาคต ตั๋ว และสินค้าที่ทดสอบให้ครบ'; END IF;
IF EXISTS(SELECT 1 FROM unnest(p_assets) a WHERE NOT EXISTS(SELECT 1 FROM equipment WHERE id=a) AND NOT EXISTS(SELECT 1 FROM media_players WHERE id=a)) THEN RAISE EXCEPTION 'ไม่พบสินค้าที่เลือก'; END IF;
IF EXISTS(SELECT 1 FROM unnest(p_tickets) t WHERE trim(t)='' OR EXISTS(SELECT 1 FROM magic_ticket_ticket_map WHERE ticket_code=trim(t))) THEN RAISE EXCEPTION 'ใช้ตั๋วใหม่ที่ยังไม่มีใบเบิกผูกไว้เท่านั้น'; END IF;
IF EXISTS(SELECT 1 FROM magic_ticket_test_sessions WHERE status<>'rolled_back' AND (asset_ids && p_assets OR ticket_codes && p_tickets)) THEN RAISE EXCEPTION 'สินค้า หรือตั๋วนี้ยังอยู่ในรอบทดสอบอื่น'; END IF;
INSERT INTO magic_ticket_test_sessions(name,starts_at,ends_at,ticket_codes,asset_ids) VALUES(trim(p_name),p_start,p_end,ARRAY(SELECT DISTINCT trim(t) FROM unnest(p_tickets)t),p_assets) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.mt_test_create(text,timestamptz,timestamptz,text[],uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mt_test_create(text,timestamptz,timestamptz,text[],uuid[]) TO authenticated;
CREATE FUNCTION public.mt_test_capture_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s magic_ticket_test_sessions%ROWTYPE; BEGIN
SELECT * INTO s FROM magic_ticket_test_sessions WHERE NEW.ticket_code=ANY(ticket_codes) AND status<>'rolled_back' ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
IF NOT FOUND THEN RETURN NEW; END IF;
IF s.status<>'open' OR now()<s.starts_at OR now()>=s.ends_at THEN RAISE EXCEPTION 'ตั๋วทดสอบอยู่นอกช่วงเวลา หรือจบรอบแล้ว'; END IF;
IF EXISTS(SELECT 1 FROM goods_issue_pending_items WHERE pending_id=NEW.pending_id AND NOT(coalesce(media_player_id,equipment_id)=ANY(s.asset_ids))) THEN RAISE EXCEPTION 'สินค้าในใบเบิกอยู่นอกขอบเขตทดสอบ'; END IF;
IF EXISTS(SELECT 1 FROM goods_issue_pending WHERE id=NEW.pending_id AND created_at<s.starts_at) THEN RAISE EXCEPTION 'ไม่รับใบเบิกเก่าก่อนเริ่มทดสอบ'; END IF;
INSERT INTO magic_ticket_test_documents(pending_id,session_id,ticket_code) VALUES(NEW.pending_id,s.id,NEW.ticket_code) ON CONFLICT(pending_id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER mt_test_capture_request AFTER INSERT ON public.magic_ticket_requests FOR EACH ROW EXECUTE FUNCTION public.mt_test_capture_document();
CREATE TRIGGER mt_test_capture_map AFTER INSERT ON public.magic_ticket_ticket_map FOR EACH ROW EXECUTE FUNCTION public.mt_test_capture_document();
CREATE FUNCTION public.mt_test_capture_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; a jsonb; r jsonb; s magic_ticket_test_sessions%ROWTYPE; v_asset uuid; BEGIN
IF TG_OP<>'INSERT' THEN b:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN a:=to_jsonb(NEW); END IF; r:=coalesce(a,b);
v_asset:=CASE WHEN TG_TABLE_NAME IN ('equipment','media_players') THEN (r->>'id')::uuid ELSE coalesce(nullif(r->>'media_player_id','')::uuid,nullif(r->>'equipment_id','')::uuid) END;
SELECT * INTO s FROM magic_ticket_test_sessions WHERE status IN ('open','ended') AND now()>=starts_at AND v_asset=ANY(asset_ids) LIMIT 1 FOR UPDATE;
IF FOUND THEN
IF s.status<>'open' OR now()>=s.ends_at THEN RAISE EXCEPTION 'สินค้าชุดทดสอบถูกพักไว้ รอคืนข้อมูลรอบทดสอบ'; END IF;
IF TG_TABLE_NAME='equipment' AND b IS NOT NULL AND a IS NOT NULL AND (b-ARRAY['quantity_in_stock','updated_at']) IS DISTINCT FROM (a-ARRAY['quantity_in_stock','updated_at']) THEN RAISE EXCEPTION 'ไม่แก้ข้อมูลหลักสินค้าระหว่างทดสอบ'; END IF;
IF TG_TABLE_NAME='media_players' AND b IS NOT NULL AND a IS NOT NULL AND (b-ARRAY['quantity','status','location_id','billboard_id','install_date','sub_media_type','updated_at']) IS DISTINCT FROM (a-ARRAY['quantity','status','location_id','billboard_id','install_date','sub_media_type','updated_at']) THEN RAISE EXCEPTION 'ไม่แก้ข้อมูลหลักเครื่องระหว่างทดสอบ'; END IF;
INSERT INTO magic_ticket_test_journal(session_id,table_name,row_id,before_row,after_row) VALUES(s.id,TG_TABLE_NAME,(r->>'id')::uuid,b,a); END IF; RETURN coalesce(NEW,OLD); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['equipment','media_players','equipment_serial_numbers','stock_location_allocations','billboard_equipment','billboard_equipment_history','media_player_billboard_history','issue_good_returns','defective_returns'] LOOP EXECUTE format('CREATE TRIGGER mt_test_journal AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.mt_test_capture_change()',t); END LOOP; END $$;
CREATE FUNCTION public.mt_test_end(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'เฉพาะ Super Admin'; END IF; UPDATE magic_ticket_test_sessions SET status='ended',ended_at=now() WHERE id=p_id AND status='open'; END $$;
REVOKE ALL ON FUNCTION public.mt_test_end(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mt_test_end(uuid) TO authenticated;
CREATE FUNCTION public.mt_test_rollback(p_id uuid,p_confirm boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s magic_ticket_test_sessions%ROWTYPE; j record; v_now jsonb; v_cols text; v_count int:=0; v_asset uuid; v_before int; v_qty int; v_doc text; BEGIN
IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'เฉพาะ Super Admin'; END IF;
SELECT * INTO s FROM magic_ticket_test_sessions WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบรอบทดสอบ'; END IF;
IF s.status='rolled_back' THEN RETURN jsonb_build_object('duplicate',true); END IF;
IF s.status<>'ended' OR p_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'จบรอบและยืนยันของจริงกลับครบก่อน'; END IF;
LOCK TABLE equipment,media_players,equipment_serial_numbers,stock_location_allocations,billboard_equipment,billboard_equipment_history,media_player_billboard_history,issue_good_returns,defective_returns,goods_issue_pending,goods_issue_pending_items,stock_movements,magic_ticket_events IN SHARE ROW EXCLUSIVE MODE;
IF EXISTS(SELECT 1 FROM stock_movements m WHERE m.equipment_id=ANY(s.asset_ids) AND m.created_at>=s.starts_at AND NOT EXISTS(SELECT 1 FROM magic_ticket_test_documents d JOIN goods_issue_pending h ON h.id=d.pending_id WHERE d.session_id=s.id AND h.document_no=m.reference_document)) THEN RAISE EXCEPTION 'พบธุรกรรมอื่นของสินค้าทดสอบ ต้องตรวจสอบก่อน ไม่คืนอัตโนมัติ'; END IF;
IF EXISTS(SELECT 1 FROM goods_issue_pending_items i JOIN goods_issue_pending h ON h.id=i.pending_id WHERE coalesce(i.media_player_id,i.equipment_id)=ANY(s.asset_ids) AND h.created_at>=s.starts_at AND NOT EXISTS(SELECT 1 FROM magic_ticket_test_documents d WHERE d.pending_id=h.id AND d.session_id=s.id)) THEN RAISE EXCEPTION 'มีใบเบิกอื่นใช้สินค้าชุดเดียวกัน ไม่คืนอัตโนมัติ'; END IF;
IF EXISTS(SELECT 1 FROM magic_ticket_events e JOIN magic_ticket_test_documents d ON d.pending_id=e.pending_id WHERE d.session_id=s.id AND e.status='applied' AND NOT(e.ticket_code=ANY(s.ticket_codes))) THEN RAISE EXCEPTION 'มีตั๋วอื่นใช้ใบเบิกทดสอบ'; END IF;
FOR j IN SELECT DISTINCT ON(table_name,row_id) * FROM magic_ticket_test_journal WHERE session_id=s.id ORDER BY table_name,row_id,id DESC LOOP EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id=$1 FOR UPDATE',j.table_name) INTO v_now USING j.row_id; IF (v_now-'updated_at') IS DISTINCT FROM (j.after_row-'updated_at') THEN RAISE EXCEPTION 'ข้อมูล % เปลี่ยนหลังทดสอบ ไม่คืนอัตโนมัติ',j.table_name; END IF; END LOOP;
UPDATE magic_ticket_test_sessions SET status='rolling_back' WHERE id=s.id;
FOR j IN SELECT * FROM magic_ticket_test_journal WHERE session_id=s.id ORDER BY id DESC LOOP
IF j.before_row IS NULL THEN EXECUTE format('DELETE FROM public.%I WHERE id=$1',j.table_name) USING j.row_id;
ELSIF j.after_row IS NULL THEN EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I,$1)).*',j.table_name,j.table_name) USING j.before_row;
ELSE SELECT string_agg(format('%I = r.%I',column_name,column_name),',') INTO v_cols FROM information_schema.columns WHERE table_schema='public' AND table_name=j.table_name AND column_name<>'id' AND is_generated='NEVER'; EXECUTE format('UPDATE public.%I t SET %s FROM jsonb_populate_record(NULL::public.%I,$1) r WHERE t.id=$2',j.table_name,v_cols,j.table_name) USING j.before_row,j.row_id; END IF; v_count:=v_count+1; END LOOP;
FOR v_asset,v_qty,v_doc IN SELECT m.equipment_id,sum(m.quantity)::int,min(m.reference_document) FROM stock_movements m WHERE m.movement_type='issue' AND m.created_at>=s.starts_at AND EXISTS(SELECT 1 FROM magic_ticket_test_documents d JOIN goods_issue_pending h ON h.id=d.pending_id WHERE d.session_id=s.id AND h.document_no=m.reference_document) GROUP BY m.equipment_id LOOP
SELECT coalesce((SELECT quantity_in_stock FROM equipment WHERE id=v_asset),(SELECT quantity FROM media_players WHERE id=v_asset)) INTO v_before;
INSERT INTO stock_movements(equipment_id,equipment_code,equipment_name,movement_type,quantity,stock_before,stock_after,reference_type,reference_id,reference_document,created_by,notes,location_id) SELECT v_asset,coalesce(e.code,m.code),coalesce(e.name,m.name),'test_rollback',v_qty,v_before-v_qty,v_before,'magic_ticket_test',s.id,v_doc,auth.uid(),'คืนข้อมูลรอบทดสอบ '||s.name,coalesce(e.location_id,m.location_id) FROM (SELECT 1) x LEFT JOIN equipment e ON e.id=v_asset LEFT JOIN media_players m ON m.id=v_asset; END LOOP;
UPDATE magic_ticket_events e SET reverted_at=coalesce(e.reverted_at,now()),reverted_reason='คืนข้อมูลรอบทดสอบ '||s.name,reverted_serial_number=coalesce(e.reverted_serial_number,e.serial_number),serial_number=NULL WHERE e.status='applied' AND EXISTS(SELECT 1 FROM magic_ticket_test_documents d WHERE d.session_id=s.id AND d.pending_id=e.pending_id);
UPDATE goods_issue_pending_items i SET status='rejected',remaining_quantity=0,installed_qty=0,returned_good_qty=0,returned_defective_qty=0,swap_returned_defective_qty=0,billboard_id=NULL,intended_billboard_id=NULL,needs_return=false,install_status='cancelled',written_off_qty=coalesce(i.issued_quantity,0),notes=concat_ws(' | ',i.notes,'คืนข้อมูลรอบทดสอบ '||s.name) WHERE EXISTS(SELECT 1 FROM magic_ticket_test_documents d WHERE d.session_id=s.id AND d.pending_id=i.pending_id);
UPDATE goods_issue_pending h SET status='cancelled',is_complete=true,remaining_quantity=0,notes=concat_ws(' | ',h.notes,'คืนข้อมูลรอบทดสอบ '||s.name) WHERE EXISTS(SELECT 1 FROM magic_ticket_test_documents d WHERE d.session_id=s.id AND d.pending_id=h.id);
UPDATE magic_ticket_test_sessions SET status='rolled_back',rolled_back_at=now(),rolled_back_by=auth.uid() WHERE id=s.id;
RETURN jsonb_build_object('duplicate',false,'restored_changes',v_count); END $$;
REVOKE ALL ON FUNCTION public.mt_test_rollback(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mt_test_rollback(uuid,boolean) TO authenticated;
REVOKE ALL ON FUNCTION public.mt_test_capture_change(),public.mt_test_capture_document() FROM PUBLIC,anon,authenticated;